const { useEffect, useMemo, useState } = React;
const price = 12000;
function CartTotal() {
  const [quantity, setQuantity] = useState(() => Number(localStorage.getItem('quantity') ?? 1));
  const total = useMemo(() => price * quantity, [quantity]);
  useEffect(() => { localStorage.setItem('quantity', String(quantity)); }, [quantity]);
  return <section><p>수량: {quantity}개</p><strong>합계: {total}원</strong><button type="button" onClick={() => setQuantity((previous) => previous + 1)}>+</button></section>;
}
ReactDOM.createRoot(document.querySelector('#root')).render(<CartTotal />);
